// Resolves packaged-product images from Open Food Facts / Open Beauty Facts using THIS machine's
// network (OFF throttles cloud IPs), then uploads each image to the Worker, which stores it in R2
// and updates D1. Produce images are generated by Workers AI via sync.mjs --kind produce.
//
// Usage:  set ADMIN_TOKEN=...   then
//         node scripts/images/sync-local.mjs --base https://zyphix.rahulsangral.workers.dev
// Options: --limit N (products to attempt, default all)  --pause ms (between lookups, default 6500 = ~9/min)
//          --maxpx 1600 (longest edge after resize when `sharp` is installed)
const args = Object.fromEntries(process.argv.slice(2).map((a, i, arr) => a.startsWith('--') ? [a.slice(2), arr[i + 1]] : []).filter(Boolean));
const base = (args.base ?? process.env.WORKER_URL ?? 'https://zyphix.in').replace(/\/$/, '');
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
let token = process.env.ADMIN_TOKEN;
if (!token) {
  // Fall back to artifacts/zyphix/.dev.vars (git-ignored):  ADMIN_TOKEN=...
  try {
    const vars = readFileSync(join(dirname(fileURLToPath(import.meta.url)), '..', '..', '.dev.vars'), 'utf8');
    token = vars.match(/^\s*ADMIN_TOKEN\s*=\s*"?([^"\r\n]+)"?/m)?.[1];
  } catch {}
}
if (!token) { console.error('ADMIN_TOKEN is required: set the env var or put ADMIN_TOKEN=... in artifacts/zyphix/.dev.vars'); process.exit(1); }
const pause = Number(args.pause ?? 6500);
const headers = { authorization: `Bearer ${token}` };
const UA = 'Zyphix/1.0 (https://zyphix.in; hello@zyphix.in)';
const sleep = ms => new Promise(r => setTimeout(r, ms));

// Optional: if `sharp` is installed we normalise images to a crisp, web-friendly size
// (max 1600px, JPEG q88) — full-resolution OFF photos can be 3–5 MB, far too heavy for product cards.
let sharp = null;
try { sharp = (await import('sharp')).default; } catch { console.log('(sharp not installed – uploading original files; run `pnpm install` in the repo root to enable resizing)'); }
const MAX_PX = Number(args.maxpx ?? 1600);

/** Open Food Facts exposes 100/200/400/full variants of the same photo; ask for the full-resolution one first. */
function imageCandidates(hit) {
  const u = hit.image_front_url ?? hit.image_url;
  if (!u) return [];
  const full = u.replace(/\.(\d{3})\.jpg$/i, '.full.jpg');
  return full !== u ? [full, u] : [u];
}

async function fetchBestImage(hit) {
  for (const u of imageCandidates(hit)) {
    const res = await fetch(u, { headers: { 'user-agent': UA } });
    if (!res.ok) continue;
    let ct = res.headers.get('content-type') ?? 'image/jpeg';
    let buf = Buffer.from(await res.arrayBuffer());
    if (sharp) {
      try { buf = await sharp(buf).rotate().resize({ width: MAX_PX, height: MAX_PX, fit: 'inside', withoutEnlargement: true }).jpeg({ quality: 88, mozjpeg: true }).toBuffer(); ct = 'image/jpeg'; } catch {}
    }
    return { buf, ct };
  }
  throw new Error('image fetch failed');
}

const BEAUTY = new Set(['Personal Care', 'Beauty & Cosmetics', 'Baby Care']);
const tokens = s => new Set(s.toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/).filter(t => t.length > 2));
function score(hit, brand, name) {
  if (!hit.image_front_url && !hit.image_url) return -1;
  const hb = String(hit.brands ?? '').toLowerCase(), hn = String(hit.product_name ?? hit.product_name_en ?? '').toLowerCase();
  let s = 0;
  if (hb.includes(brand.toLowerCase().split(' ')[0])) s += 3;
  const have = tokens(hn + ' ' + hb); for (const t of tokens(name)) if (have.has(t)) s += 1;
  if (String(hit.countries_tags ?? '').includes('india')) s += 1;
  return s;
}

async function search(host, q) {
  const u = new URL(`https://${host}/cgi/search.pl`);
  u.searchParams.set('search_terms', q); u.searchParams.set('search_simple', '1'); u.searchParams.set('action', 'process');
  u.searchParams.set('json', '1'); u.searchParams.set('page_size', '10');
  u.searchParams.set('fields', 'code,product_name,product_name_en,brands,image_front_url,image_url,countries_tags');
  for (let attempt = 0; attempt < 4; attempt++) {
    const res = await fetch(u, { headers: { 'user-agent': UA, accept: 'application/json' } });
    if (res.status === 429 || res.status === 503) { console.log(`   rate limited by ${host}, waiting 90s…`); await sleep(90000); continue; }
    if (!res.ok) throw new Error(`search ${res.status}`);
    try { return (await res.json()).products ?? []; } catch { throw new Error('non-JSON reply'); }
  }
  throw new Error('rate limited repeatedly');
}

const pending = await fetch(`${base}/admin/images/pending?kind=packaged&limit=${args.limit ?? 5000}`, { headers }).then(r => r.json());
if (!Array.isArray(pending)) { console.error('could not fetch pending list:', pending); process.exit(1); }
console.log(`${pending.length} packaged products to resolve (~${Math.round(pending.length * pause / 60000)} min)`);

const totals = { ready: 0, not_found: 0, failed: 0 };
for (const [i, row] of pending.entries()) {
  const label = `${row.brand} ${row.name}`;
  const bare = row.name.toLowerCase().startsWith(row.brand.toLowerCase()) ? (row.name.slice(row.brand.length).trim() || row.name) : row.name;
  const first = BEAUTY.has(row.category) ? 'world.openbeautyfacts.org' : 'world.openfoodfacts.org';
  const hosts = [first, first.includes('beauty') ? 'world.openfoodfacts.org' : 'world.openbeautyfacts.org'];
  try {
    let best = null, bestScore = 2, src = null;
    for (const host of hosts) {
      const hits = await search(host, `${row.brand} ${bare}`);
      for (const h of hits) { const s = score(h, row.brand, bare); if (s > bestScore) { bestScore = s; best = h; src = host.includes('beauty') ? 'openbeautyfacts' : 'openfoodfacts'; } }
      if (best || hits.length) break;
      await sleep(pause);
    }
    if (!best) {
      await fetch(`${base}/admin/images/not-found?brand=${encodeURIComponent(row.brand)}&name=${encodeURIComponent(row.name)}`, { method: 'POST', headers });
      totals.not_found++; console.log(`not_found ${label}`);
    } else {
      const { buf, ct } = await fetchBestImage(best);
      const put = await fetch(`${base}/admin/images/put?brand=${encodeURIComponent(row.brand)}&name=${encodeURIComponent(row.name)}&source=${src}&barcode=${best.code}`,
        { method: 'PUT', headers: { ...headers, 'content-type': ct }, body: buf });
      if (!put.ok) throw new Error(`upload ${put.status} ${await put.text()}`);
      totals.ready++; console.log(`ready     ${label} (${src} ${best.code})`);
    }
  } catch (err) {
    totals.failed++; console.log(`failed    ${label} – ${err.message}`);
  }
  if ((i + 1) % 25 === 0) console.log(`-- ${i + 1}/${pending.length}  ready ${totals.ready} · not_found ${totals.not_found} · failed ${totals.failed}`);
  await sleep(pause);
}
console.log('done', totals);
console.table(await fetch(`${base}/admin/images/status`, { headers }).then(r => r.json()));
